  logistic_model,
  newdata = model_features,
  type = "response"
))

assign_risk_band <- function(score, reference_scores = cleaned_data$predicted_risk) {
  reference_scores <- sort(reference_scores[is.finite(reference_scores)])
  percentile <- findInterval(score, reference_scores, left.open = FALSE) / length(reference_scores)
  factor(
    dplyr::case_when(
      percentile <= 0.50 ~ "Low",
      percentile <= 0.80 ~ "Moderate",
      percentile <= 0.95 ~ "High",
      TRUE ~ "Very high"
    ),
    levels = c("Low", "Moderate", "High", "Very high")
  )
}

cleaned_data$risk_band <- assign_risk_band(cleaned_data$predicted_risk)
cleaned_data$age_band <- cut(
  cleaned_data$age,
  breaks = c(-Inf, 29, 44, 59, Inf),
  labels = c("<30", "30-44", "45-59", "60+"),
  right = TRUE
)
cleaned_data$age_band <- as.character(cleaned_data$age_band)
cleaned_data$age_band[is.na(cleaned_data$age_band)] <- "Missing"
cleaned_data$income_status <- ifelse(
  cleaned_data$monthly_income_missing == 1,
  "Missing",
  "Observed"
)
cleaned_data$delinquency_90_status <- dplyr::case_when(
  is.na(cleaned_data$number_of_times90days_late) ~ "Missing",
  cleaned_data$number_of_times90days_late > 0 ~ "One or more 90+ day events",
  TRUE ~ "No 90+ day events"
)

