format_number <- function(value, digits = 0) {
  ifelse(
    is.na(value),
    "—",
    formatC(value, format = "f", digits = digits, big.mark = ",")
  )
}

format_percentage <- function(value, digits = 1) {
  ifelse(
    is.na(value),
    "—",
    paste0(formatC(value * 100, format = "f", digits = digits), "%")
  )
}

metric_card <- function(label, value, note) {
  tags$div(
    class = "metric-card",
    tags$div(class = "metric-label", label),
    tags$div(class = "metric-value", value),
    tags$div(class = "metric-note", note)
  )
}

page_intro <- function(kicker, title, description) {
  tags$div(
    class = "page-intro",
    tags$div(class = "page-kicker", kicker),
    tags$h1(title),
    tags$p(description)
  )
}

plot_theme <- function() {
  graphics::par(
