          numericInput("sim_30_59", "30-59 days late count", value = 0, min = 0, step = 1),
          numericInput("sim_60_89", "60-89 days late count", value = 0, min = 0, step = 1),
          numericInput("sim_90", "90+ days late count", value = 0, min = 0, step = 1),
          numericInput("sim_real_estate", "Real-estate loans or lines", value = 1, min = 0, step = 1),
          checkboxInput("sim_dependents_missing", "Dependents unavailable", value = FALSE),
          numericInput("sim_dependents", "Dependents", value = 0, min = 0, step = 1)
        ),
        mainPanel(
          div(class = "panel", h3("Demonstration result"), uiOutput("simulator_result")),
          div(class = "panel", h3("Model contribution view"), div(class = "panel-caption", "These are directional contributions from the saved logistic terms, not causal explanations."), tableOutput("simulator_drivers")),
          div(class = "notice", strong("Responsible use: "), "Do not use this simulator to make or support a real credit decision. The source data is public, historical, and not a complete SME application record.")
        )
      )
    )
  )
)

server <- function(input, output, session) {
  overview_data <- reactive({
    data <- cleaned_data
    if (input$overview_age != "All") data <- data[data$age_band == input$overview_age, , drop = FALSE]
    if (input$overview_income != "All") data <- data[data$income_status == input$overview_income, , drop = FALSE]
    if (input$overview_delinquency != "All") data <- data[data$delinquency_90_status == input$overview_delinquency, , drop = FALSE]
    data
  })

  output$overview_cards <- renderUI({
    data <- overview_data()
    default_rate <- if (nrow(data) > 0) mean(data$serious_dlqin2yrs) else NA_real_
    high_rate <- if (nrow(data) > 0) mean(data$risk_band %in% c("High", "Very high")) else NA_real_
    tagList(
      div(class = "metric-grid",
        metric_card("Borrowers", format_number(nrow(data)), "Filtered training records"),
        metric_card("Observed default rate", format_percentage(default_rate), "SeriousDlqin2yrs = 1"),
        metric_card("Mean predicted risk", format_percentage(mean(data$predicted_risk), 2), "Saved logistic model"),
        metric_card("High / very high", format_percentage(high_rate), "Demonstration risk bands")
      )
    )
  })

  output$overview_risk_bands <- renderPlot({
    data <- overview_data()
    counts <- table(factor(data$risk_band, levels = c("Low", "Moderate", "High", "Very high")))
    plot_theme()
    graphics::barplot(
      counts,
      col = c("#8B9D83", "#C08E3A", "#B08B6E", "#C66B3D"),
      names.arg = names(counts),
      ylab = "Borrower count",
      main = paste0("Risk bands (n = ", format_number(nrow(data)), ")")
    )
  }, res = 110)

  output$overview_age_default <- renderPlot({
    data <- overview_data()
    if (nrow(data) == 0) {
      plot_theme()
      graphics::plot.new()
      graphics::title("No borrowers match the selected filters.")
      return(invisible(NULL))
    }
    summary <- data |>
      dplyr::group_by(age_band) |>
      dplyr::summarise(borrower_count = dplyr::n(), default_rate = mean(serious_dlqin2yrs), .groups = "drop") |>
      dplyr::mutate(age_band = factor(age_band, levels = c("<30", "30-44", "45-59", "60+", "Missing"))) |>
      dplyr::arrange(age_band)
    plot_theme()
    locations <- graphics::barplot(
      summary$default_rate * 100,
      names.arg = summary$age_band,
      col = "#606C38",
      ylab = "Observed default rate (%)",
      main = "Default rate by age band",
      ylim = c(0, max(summary$default_rate * 100) * 1.28)
    )
    graphics::text(
      locations,
      summary$default_rate * 100,
      labels = paste0(format_percentage(summary$default_rate), " (n=", format_number(summary$borrower_count), ")"),
      pos = 3,
      cex = 0.75
    )
  }, res = 110)

  output$overview_summary_table <- renderTable({
    data <- overview_data()
    if (nrow(data) == 0) return(data.frame(Message = "No borrowers match the selected filters."))
    data |>
      dplyr::group_by(risk_band) |>
      dplyr::summarise(
        Borrowers = dplyr::n(),
        `Observed default rate` = format_percentage(mean(serious_dlqin2yrs)),
        `Mean predicted risk` = format_percentage(mean(predicted_risk), 2),
        .groups = "drop"
      ) |>
      dplyr::rename(`Risk band` = risk_band)
  }, striped = TRUE, bordered = FALSE, spacing = "s", rownames = FALSE)

  output$portfolio_panel_title <- renderText({
    choices <- c(
      age_band = "Default rate by age band",
      income_status = "Default rate by income availability",
      delinquency_90_status = "Default rate by 90+ day history",
      risk_band = "Default rate by demonstration risk band"
    )
    choices[[input$portfolio_group]]
  })

  portfolio_summary <- reactive({
    data <- cleaned_data
    group <- input$portfolio_group
    data |>
      dplyr::group_by(.data[[group]]) |>
      dplyr::summarise(
        borrower_count = dplyr::n(),
        default_count = sum(serious_dlqin2yrs == 1),
        default_rate = mean(serious_dlqin2yrs),
        mean_predicted_risk = mean(predicted_risk),
        .groups = "drop"
      ) |>
      dplyr::rename(segment = all_of(group)) |>
      dplyr::arrange(dplyr::desc(default_rate))
  })

  output$portfolio_segment_plot <- renderPlot({
    summary <- portfolio_summary()
    plot_theme()
    locations <- graphics::barplot(
      summary$default_rate * 100,
      names.arg = summary$segment,
      col = "#C66B3D",
      ylab = "Observed default rate (%)",
      main = "Observed default rate",
      ylim = c(0, max(summary$default_rate * 100) * 1.28),
      las = 2
    )
    graphics::text(
      locations,
      summary$default_rate * 100,
      labels = paste0(format_percentage(summary$default_rate), " (n=", format_number(summary$borrower_count), ")"),
      pos = 3,
      cex = 0.75
    )
  }, res = 110)

  output$portfolio_segment_table <- renderTable({
    portfolio_summary() |>
      dplyr::mutate(
        default_rate = format_percentage(default_rate),
        mean_predicted_risk = format_percentage(mean_predicted_risk, 2)
      ) |>
      dplyr::rename(
        Segment = segment,
        Borrowers = borrower_count,
        Defaults = default_count,
        `Observed default rate` = default_rate,
        `Mean predicted risk` = mean_predicted_risk
      )
  }, striped = TRUE, bordered = FALSE, spacing = "s", rownames = FALSE)

  output$stat_missingness <- renderPlot({
    values <- missingness |>
      dplyr::filter(missing_count > 0) |>
      dplyr::arrange(missing_pct)
    labels <- c(
      monthly_income = "Monthly income",
      number_of_dependents = "Dependents",
      number_of_time30_59days_past_due_not_worse = "30-59 days late",
      number_of_times90days_late = "90+ days late",
      number_of_time60_89days_past_due_not_worse = "60-89 days late",
      age = "Age"
    )
    plot_theme()
    graphics::barplot(
      values$missing_pct * 100,
      names.arg = unname(labels[values$variable]),
      horiz = TRUE,
      las = 1,
      col = "#B08B6E",
      xlab = "Missing rows (%)",
      main = "Source missingness"
    )
  }, res = 110)

  output$stat_distribution <- renderPlot({
    variable <- input$stat_distribution_variable
    if (is.null(variable) || !variable %in% unname(stat_distribution_variables)) {
      variable <- unname(stat_distribution_variables[[1]])
    }
    label <- names(stat_distribution_variables)[match(variable, stat_distribution_variables)]
    values <- cleaned_data[[variable]]
    target <- cleaned_data$serious_dlqin2yrs
    keep <- is.finite(values) & !is.na(target)

    plot_theme()
    if (!any(keep)) {
      graphics::plot.new()
      graphics::title(main = paste("Distribution of", label), sub = "No finite observations available")
      return(invisible(NULL))
    }

    group <- factor(
      ifelse(target[keep] == 1, "Defaulted", "Non-defaulted"),
      levels = c("Non-defaulted", "Defaulted")
    )
    distribution_values <- values[keep]
    counts <- table(group)
    graphics::boxplot(
      distribution_values ~ group,
      col = c("#8B9D83", "#C66B3D"),
      ylab = "Source value",
      main = paste("Distribution of", label),
      outline = FALSE
    )
    graphics::mtext(
      paste0("Non-missing n: ", format_number(length(distribution_values)), " | ", paste(names(counts), counts, sep = " n=", collapse = "; ")),
      side = 3,
      line = 0.2,
      cex = 0.75,
      col = "#60645A"
    )
  }, res = 110)

  output$stat_correlation <- renderPlot({
    matrix <- as.matrix(correlation_data[, -1])
    rownames(matrix) <- correlation_data$variable
    labels <- unname(pretty_feature_labels[colnames(matrix)])
    plot_theme()
    graphics::par(mar = c(10, 10, 3, 2))
    graphics::image(
      seq_len(ncol(matrix)),
      seq_len(nrow(matrix)),
      matrix[nrow(matrix):1, , drop = FALSE],
      col = grDevices::colorRampPalette(c("#2166ac", "#F7F3EA", "#C66B3D"))(100),
      zlim = c(-1, 1),
      axes = FALSE,
      main = "Spearman correlation"
    )
    graphics::axis(1, at = seq_along(labels), labels = labels, las = 2, cex.axis = 0.7)
    graphics::axis(2, at = seq_along(labels), labels = rev(labels), las = 2, cex.axis = 0.7)
  }, res = 110)

  output$stat_numeric_table <- renderTable({
    numeric_comparisons |>
      dplyr::select(variable, n_nonmissing, mean_defaulted, mean_non_defaulted, median_defaulted, median_non_defaulted, wilcoxon_p_value) |>
      dplyr::mutate(
        variable = unname(pretty_feature_labels[variable]),
        mean_defaulted = format_number(mean_defaulted, 2),
        mean_non_defaulted = format_number(mean_non_defaulted, 2),
        median_defaulted = format_number(median_defaulted, 2),
        median_non_defaulted = format_number(median_non_defaulted, 2),
        wilcoxon_p_value = ifelse(wilcoxon_p_value < 1e-6, "<1e-6", formatC(wilcoxon_p_value, format = "f", digits = 4))
      ) |>
      dplyr::rename(
        Variable = variable,
        `Non-missing` = n_nonmissing,
        `Mean defaulted` = mean_defaulted,
        `Mean non-defaulted` = mean_non_defaulted,
        `Median defaulted` = median_defaulted,
        `Median non-defaulted` = median_non_defaulted,
        `Wilcoxon p-value` = wilcoxon_p_value
      )
  }, striped = TRUE, bordered = FALSE, spacing = "s", rownames = FALSE)

  output$stat_segment_table <- renderTable({
    segment_rates |>
      dplyr::filter(segment %in% c("age_band", "income_band", "dependents_band")) |>
      dplyr::mutate(
        default_rate = format_percentage(default_rate),
        ci = paste0(format_percentage(default_rate_ci_lower), " to ", format_percentage(default_rate_ci_upper))
      ) |>
      dplyr::select(segment, band, borrower_count, default_rate, ci) |>
      dplyr::rename(
        Segment = segment,
        Band = band,
        Borrowers = borrower_count,
        `Default rate` = default_rate,
        `Wilson 95% interval` = ci
      )
  }, striped = TRUE, bordered = FALSE, spacing = "s", rownames = FALSE)

  output$monitoring_prediction_plot <- renderPlot({
    values <- monitoring_psi |>
      dplyr::filter(metric_type == "prediction", variable == "predicted_risk")
    plot_theme()
    graphics::par(mar = c(8, 5, 3, 2))
    distribution_matrix <- rbind(values$reference_pct, values$comparison_pct)
    graphics::barplot(
      distribution_matrix,
      beside = TRUE,
      names.arg = values$bin,
      col = c("#8B9D83", "#C66B3D"),
      border = NA,
      las = 2,
      ylab = "Share of non-missing scores",
      main = "Prediction distribution by reference bin"
    )
    graphics::legend(
      "topright",
      legend = c("Reference train", "Comparison test"),
      fill = c("#8B9D83", "#C66B3D"),
      bty = "n"
    )
  }, res = 110)

  output$monitoring_psi_plot <- renderPlot({
    values <- monitoring_feature_drift |>
      dplyr::arrange(psi) |>
      dplyr::slice_tail(n = min(10, nrow(monitoring_feature_drift)))
    plot_theme()
    graphics::par(mar = c(5, 13, 3, 2))
    graphics::barplot(
      rev(values$psi),
      names.arg = unname(monitoring_feature_labels[rev(values$variable)]),
      horiz = TRUE,
      las = 1,
      col = "#B08B6E",
      border = NA,
      xlab = "PSI",
      main = "Feature distribution shift",
      cex.names = 0.8
    )
    graphics::abline(v = 0.10, lty = 2, col = "#C08E3A")
  }, res = 110)

  output$monitoring_summary_table <- renderTable({
    monitoring_summary |>
      dplyr::rename(
        Check = check,
        Status = status,
        Details = details
      )
  }, striped = TRUE, bordered = FALSE, spacing = "s", rownames = FALSE)

  output$monitoring_feature_table <- renderTable({
    monitoring_feature_drift |>
      dplyr::slice_head(n = 10) |>
      dplyr::mutate(
        variable = unname(monitoring_feature_labels[variable]),
        reference_mean = format_number(reference_mean, 3),
        comparison_mean = format_number(comparison_mean, 3),
        reference_median = format_number(reference_median, 3),
        comparison_median = format_number(comparison_median, 3),
        psi = format_number(psi, 4),
        missing_rate_difference = format_percentage(missing_rate_difference, 2)
      ) |>
      dplyr::select(variable, reference_mean, comparison_mean, reference_median, comparison_median, missing_rate_difference, psi, psi_interpretation) |>
      dplyr::rename(
        Feature = variable,
        `Reference mean` = reference_mean,
        `Comparison mean` = comparison_mean,
        `Reference median` = reference_median,
        `Comparison median` = comparison_median,
        `Missing-rate change` = missing_rate_difference,
        PSI = psi,
        Interpretation = psi_interpretation
      )
  }, striped = TRUE, bordered = FALSE, spacing = "s", rownames = FALSE)

  output$monitoring_calibration_table <- renderTable({
    monitoring_calibration |>
      dplyr::filter(period == "comparison_test") |>
      dplyr::mutate(
        predicted_default_rate = format_percentage(predicted_default_rate),
        observed_default_rate = format_percentage(observed_default_rate),
        calibration_gap = format_percentage(calibration_gap),
        absolute_calibration_gap = format_percentage(absolute_calibration_gap)
      ) |>
      dplyr::select(decile, borrower_count, predicted_default_rate, observed_default_rate, calibration_gap, absolute_calibration_gap) |>
      dplyr::rename(
        Decile = decile,
        Borrowers = borrower_count,
        `Predicted default rate` = predicted_default_rate,
        `Observed default rate` = observed_default_rate,
        `Calibration gap` = calibration_gap,
        `Absolute gap` = absolute_calibration_gap
      )
  }, striped = TRUE, bordered = FALSE, spacing = "s", rownames = FALSE)

  output$model_recommendation <- renderUI({
    woe_metrics <- model_metrics[model_metrics$model == "Logistic_WOE", , drop = FALSE]
    xgb_metrics <- model_metrics[model_metrics$model == "XGBoost", , drop = FALSE]
    if (nrow(woe_metrics) == 0 || nrow(xgb_metrics) == 0) {
      return(div(class = "notice", strong("Held-out interpretation: "), "Model comparison artifacts are incomplete."))
    }

    div(
      class = "notice",
      strong("Held-out interpretation: "),
      paste0(
        "WoE logistic is the strongest interpretable demonstration candidate (ROC-AUC ",
        format_number(woe_metrics$roc_auc[[1]], 3),
        "; Brier score ",
        format_number(woe_metrics$brier_score[[1]], 3),
        "). XGBoost has the best ranking result (ROC-AUC ",
        format_number(xgb_metrics$roc_auc[[1]], 3),
        ") but weaker probability accuracy (Brier score ",
        format_number(xgb_metrics$brier_score[[1]], 3),
        ") after class weighting. These results are held-out demonstrations, not lending policy."
      )
    )
  })

  output$model_metrics_table <- renderTable({
    model_metrics |>
      dplyr::mutate(
        model = unname(model_display_labels[model]),
        default_rate = format_percentage(default_rate),
        roc_auc = format_number(roc_auc, 3),
        pr_auc = format_number(pr_auc, 3),
        ks = format_number(ks, 3),
        brier_score = format_number(brier_score, 3)
      ) |>
      dplyr::select(model, borrower_count, default_rate, roc_auc, pr_auc, ks, brier_score) |>
      dplyr::rename(
        Model = model,
        `Test borrowers` = borrower_count,
        `Default rate` = default_rate,
        `ROC-AUC` = roc_auc,
        `PR-AUC` = pr_auc,
        KS = ks,
        `Brier score` = brier_score
      )
  }, striped = TRUE, bordered = FALSE, spacing = "s", rownames = FALSE)

  output$model_roc <- renderPlot({
    plot_theme()
    colors <- c(Logistic = "#2166ac", Logistic_WOE = "#8c6bb1", CART = "#b2182b", RandomForest = "#606C38", XGBoost = "#C66B3D")
    graphics::plot(
      0,
      0,
      type = "n",
      xlim = c(0, 1),
      ylim = c(0, 1),
      xlab = "False-positive rate",
      ylab = "True-positive rate",
      main = "Held-out ROC comparison"
    )
    for (model_name in unique(model_roc_curves$model)) {
      values <- model_roc_curves[model_roc_curves$model == model_name, , drop = FALSE]
      graphics::lines(
        values$false_positive_rate,
        values$true_positive_rate,
        col = colors[[model_name]],
        lwd = 2
      )
    }
    graphics::abline(0, 1, lty = 2, col = "#8B9D83")
    legend_labels <- paste0(
      unname(model_display_labels[model_metrics$model]),
      " ROC-AUC = ",
      format_number(model_metrics$roc_auc, 3)
    )
    graphics::legend(
      "bottomright",
      legend = legend_labels,
      col = colors[model_metrics$model],
      lwd = 2,
      bty = "n"
    )
  }, res = 110)

  output$model_calibration_plot <- renderPlot({
    plot_theme()
    graphics::plot(0, 0, type = "n", xlim = c(0, max(model_calibration$predicted_default_rate) * 1.05), ylim = c(0, max(model_calibration$observed_default_rate) * 1.05), xlab = "Mean predicted default rate", ylab = "Observed default rate", main = "Calibration by risk decile")
    graphics::abline(0, 1, lty = 2, col = "#8B9D83")
    colors <- c(Logistic = "#2166ac", Logistic_WOE = "#8c6bb1", CART = "#b2182b", RandomForest = "#606C38", XGBoost = "#C66B3D")
    for (model_name in unique(model_calibration$model)) {
      values <- model_calibration[model_calibration$model == model_name, , drop = FALSE]
      graphics::lines(values$predicted_default_rate, values$observed_default_rate, type = "b", col = colors[[model_name]], lwd = 2, pch = 19)
    }
    graphics::legend("topleft", legend = unname(model_display_labels[names(colors)]), col = colors, lwd = 2, pch = 19, bty = "n")
  }, res = 110)

  output$model_lift_plot <- renderPlot({
    plot_theme()
    colors <- c(Logistic = "#2166ac", Logistic_WOE = "#8c6bb1", CART = "#b2182b", RandomForest = "#606C38", XGBoost = "#C66B3D")
    graphics::plot(1:10, rep(NA_real_, 10), type = "n", xlim = c(1, 10), ylim = c(0, max(model_lift$lift) * 1.05), xlab = "Risk decile (1 = highest predicted risk)", ylab = "Observed lift", main = "Lift by risk decile")
    graphics::abline(h = 1, lty = 2, col = "#8B9D83")
    for (model_name in unique(model_lift$model)) {
      values <- model_lift[model_lift$model == model_name, , drop = FALSE]
      graphics::lines(values$decile, values$lift, type = "b", col = colors[[model_name]], lwd = 2, pch = 19)
    }
    graphics::legend("topright", legend = unname(model_display_labels[names(colors)]), col = colors, lwd = 2, pch = 19, bty = "n")
  }, res = 110)

  output$model_threshold_table <- renderTable({
    model_thresholds |>
      dplyr::mutate(
        threshold = format_percentage(threshold),
        sensitivity = format_percentage(sensitivity),
        specificity = format_percentage(specificity),
        precision = format_percentage(precision),
        false_negative_rate = format_percentage(false_negative_rate),
        flagged_rate = format_percentage(flagged_rate)
      ) |>
      dplyr::select(model, threshold, sensitivity, specificity, precision, false_negative_rate, flagged_rate) |>
      dplyr::rename(
        Model = model,
        Threshold = threshold,
        Sensitivity = sensitivity,
        Specificity = specificity,
        Precision = precision,
        `False-negative rate` = false_negative_rate,
        `Flagged rate` = flagged_rate
      )
  }, striped = TRUE, bordered = FALSE, spacing = "s", rownames = FALSE)

  simulator_features <- reactive({
    data.frame(
      age = input$sim_age,
      revolving_utilization_of_unsecured_lines = input$sim_utilization,
      debt_ratio = input$sim_debt_ratio,
      monthly_income = if (isTRUE(input$sim_income_missing)) NA_real_ else input$sim_income,
      number_of_open_credit_lines_and_loans = input$sim_open_lines,
      number_of_time30_59days_past_due_not_worse = input$sim_30_59,
      number_of_time60_89days_past_due_not_worse = input$sim_60_89,
      number_of_times90days_late = input$sim_90,
      number_real_estate_loans_or_lines = input$sim_real_estate,
      number_of_dependents = if (isTRUE(input$sim_dependents_missing)) NA_real_ else input$sim_dependents,
      revolving_utilization_gt_1 = as.integer(input$sim_utilization > 1),
      debt_ratio_gt_10 = as.integer(input$sim_debt_ratio > 10)
    )
  })

  simulator_prediction <- reactive({
    features <- build_model_features(simulator_features())
    processed <- apply_model_preprocessor(features, model_preprocessor)
    score <- as.numeric(stats::predict(logistic_model, newdata = processed, type = "response"))
    list(score = score, band = assign_risk_band(score), features = processed)
  })

  output$simulator_result <- renderUI({
    result <- simulator_prediction()
    div(
      class = "risk-result",
      div(class = "risk-score", div("Predicted probability of serious delinquency"), div(class = "value", format_percentage(result$score, 2)), div("Saved logistic model")),
      div(class = "risk-band", div("Demonstration risk band"), div(class = "value", as.character(result$band)), div("Percentile-based portfolio comparison"))
    )
  })

  output$simulator_drivers <- renderTable({
    result <- simulator_prediction()
    coefficients <- stats::coef(logistic_model)[model_preprocessor$feature_names]
    medians <- model_preprocessor$medians[model_preprocessor$feature_names]
    feature_values <- as.numeric(result$features[1, model_preprocessor$feature_names])
    names(feature_values) <- model_preprocessor$feature_names
    contributions <- (feature_values - medians) * coefficients
    contributions <- sort(contributions[is.finite(contributions)], decreasing = TRUE)
    positive <- head(contributions[contributions > 0], 4)
    negative <- head(contributions[contributions < 0], 2)
    driver_rows <- rbind(
      if (length(positive) > 0) data.frame(Direction = "Higher estimated risk", Feature = names(positive), contribution = unname(positive)) else NULL,
      if (length(negative) > 0) data.frame(Direction = "Lower estimated risk", Feature = names(negative), contribution = unname(negative)) else NULL
    )
    if (is.null(driver_rows) || nrow(driver_rows) == 0) {
      return(data.frame(Message = "No directional contributions available."))
    }
    data.frame(
      Direction = driver_rows$Direction,
      Feature = unname(pretty_feature_labels[driver_rows$Feature]),
      `Relative contribution` = format_number(driver_rows$contribution, 4),
      check.names = FALSE,
      row.names = NULL
    )
  }, striped = TRUE, bordered = FALSE, spacing = "s", rownames = FALSE)
}

shinyApp(ui, server)
